# এসএসসি সাধারণ গণিত অধ্যায় ১ (বাস্তব সংখ্যা): মৌলিক সৃজনশীল প্রশ্ন — উদ্দীপক + ক (২), খ (৪), গ (৪)
from sqlib import rec, F
import json, os, sympy as sp
r6=sp.sqrt(6)
# যাচাই
p,q=rec(0,'','23'),rec(1,'','2'); assert p==F(23,99) and q==F(11,9) and p+q==F(16,11) and p*q==F(23,81)
assert ''.join(str((23*10**k)//81%10) for k in range(1,19))=='283950617283950617' and ''.join(str((16*10**k)//11%10) for k in range(1,7))=='454545'
x=(sp.sqrt(3)+sp.sqrt(2))/(sp.sqrt(3)-sp.sqrt(2)); assert sp.expand(sp.radsimp(x))==5+2*r6 and sp.expand(sp.radsimp(x+1/x))==10 and sp.expand(sp.radsimp(x**2+1/x**2))==98 and sp.expand(sp.radsimp(x**3+1/x**3))==970
s=('142857'*17)[:100]; assert s[99]=='8' and sum(map(int,s))==447
assert all((k**3-k)%6==0 for k in range(1,60)) and all((k*k-1)%8==0 for k in range(1,60,2)) and all((k*(k+1))%2==0 for k in range(1,60))
A,B=rec(2,'','35'),rec(1,'4','7'); assert A==F(233,99) and B==F(133,90) and A-B==F(289,330) and A+B==F(3793,990) and round(3793/990,3)==3.831
assert ''.join(str((289*10**k)//330%10) for k in range(1,8))=='8757575'
CQ=[
("p = 0.232323… , q = 1.222… এবং r = √5 তিনটি বাস্তব সংখ্যা।",
 ["p ও q কে সাধারণ ভগ্নাংশে প্রকাশ কর।","p + q এবং p × q কে আবৃত্ত দশমিকে প্রকাশ কর এবং p × q এর আবৃত্ত অংশে কয়টি অঙ্ক আছে নির্ণয় কর।","প্রমাণ কর যে, r একটি অমূলদ সংখ্যা এবং p + r মূলদ না অমূলদ যুক্তিসহ লেখ।"],
 "ক) p = 23/99, q = 1 + 2/9 = 11/9\nখ) p + q = 23/99 + 121/99 = 144/99 = 16/11 = 1.454545… (45 আবৃত্ত)\np × q = (23/99)(11/9) = 23/81 = 0.283950617283950617… ⇒ আবৃত্ত অংশ 283950617, অঙ্কসংখ্যা 9\nগ) ধরি √5 = a/b (a, b সহমৌলিক)। a² = 5b² ⇒ a, 5 দ্বারা বিভাজ্য; a = 5c ⇒ b² = 5c² ⇒ b-ও 5 দ্বারা বিভাজ্য — সহমৌলিকতার বিরোধী ⇒ √5 অমূলদ।\np + r মূলদ হলে r = (p + r) − p মূলদ হতো, যা অসম্ভব ⇒ p + r অমূলদ।"),
("a = √3, b = √2 এবং x = (a + b)/(a − b)।",
 ["a² − b² এর মান নির্ণয় কর এবং ab মূলদ না অমূলদ বল।","দেখাও যে, x = 5 + 2√6 এবং x + 1/x একটি মূলদ সংখ্যা।","x² + 1/x² এবং x³ + 1/x³ এর মান নির্ণয় কর।"],
 "ক) a² − b² = 3 − 2 = 1; ab = √6, যা অমূলদ।\nখ) লব ও হরকে (√3 + √2) দিয়ে গুণ করে x = (3 + 2 + 2√6)/(3 − 2) = 5 + 2√6\nএকইভাবে 1/x = 5 − 2√6 ⇒ x + 1/x = 10, যা মূলদ।\nগ) x² + 1/x² = (x + 1/x)² − 2 = 100 − 2 = 98\nx³ + 1/x³ = (x + 1/x)³ − 3(x + 1/x) = 1000 − 30 = 970"),
("0.31 ও 0.32 দুইটি দশমিক সংখ্যা এবং 1/7 একটি সাধারণ ভগ্নাংশ।",
 ["1/7 কে দশমিক ভগ্নাংশে প্রকাশ কর।","0.31 ও 0.32 এর মধ্যে দুইটি মূলদ ও দুইটি অমূলদ সংখ্যা নির্ণয় কর।","1/7 এর দশমিক বিস্তারে দশমিক বিন্দুর পরের 100তম অঙ্ক এবং প্রথম 100টি অঙ্কের যোগফল নির্ণয় কর।"],
 "ক) 1/7 = 0.142857142857… (142857 আবৃত্ত)\nখ) মূলদ: যেমন 0.311 ও 0.315\nঅমূলদ: যেমন 0.3101001000100001… এবং 0.3120120012000120… (অসীম ও অনাবৃত্ত দশমিক)\nগ) আবৃত্ত অংশে 6টি অঙ্ক; 100 = 6 × 16 + 4 ⇒ 100তম অঙ্ক = আবৃত্ত অংশের 4র্থ অঙ্ক = 8\nযোগফল = 16 × (1 + 4 + 2 + 8 + 5 + 7) + (1 + 4 + 2 + 8) = 432 + 15 = 447"),
("n যেকোনো স্বাভাবিক সংখ্যা।",
 ["প্রমাণ কর যে, n(n + 1) একটি জোড় সংখ্যা।","প্রমাণ কর যে, n³ − n সর্বদা 6 দ্বারা বিভাজ্য।","n বিজোড় হলে প্রমাণ কর যে, n² − 1 সংখ্যাটি 8 দ্বারা বিভাজ্য এবং n = 7 এর জন্য যাচাই কর।"],
 "ক) n ও n + 1 ক্রমিক, তাই এদের একটি জোড় ⇒ গুণফল n(n + 1) জোড়।\nখ) n³ − n = (n − 1)n(n + 1), তিনটি ক্রমিক স্বাভাবিক সংখ্যার গুণফল।\nএদের অন্তত একটি জোড় এবং একটি 3 দ্বারা বিভাজ্য ⇒ গুণফল 2 × 3 = 6 দ্বারা বিভাজ্য।\nগ) n = 2k + 1 ⇒ n² − 1 = 4k² + 4k = 4k(k + 1); k(k + 1) জোড় ⇒ n² − 1, 8 দ্বারা বিভাজ্য।\nযাচাই: n = 7 ⇒ 49 − 1 = 48 = 8 × 6 ✓"),
("A = 2.353535… এবং B = 1.4777… (শুধু 7 আবৃত্ত) দুইটি আবৃত্ত দশমিক সংখ্যা।",
 ["A কে সাধারণ ভগ্নাংশে প্রকাশ কর।","B কে সাধারণ ভগ্নাংশে প্রকাশ কর এবং A − B এর মান আবৃত্ত দশমিকে প্রকাশ কর।","A + B এর মান নির্ণয় কর এবং তিন দশমিক স্থান পর্যন্ত ও তিন তাৎপর্যপূর্ণ অঙ্ক পর্যন্ত আসন্ন মান লেখ।"],
 "ক) A = 2 + 35/99 = 233/99\nখ) B = (147 − 14)/90 = 133/90\nA − B = 233/99 − 133/90 = (2330 − 1463)/990 = 867/990 = 289/330 = 0.8757575… (75 আবৃত্ত)\nগ) A + B = (2330 + 1463)/990 = 3793/990 = 3.8313131…\nতিন দশমিক স্থান পর্যন্ত 3.831; তিন তাৎপর্যপূর্ণ অঙ্ক পর্যন্ত 3.83"),
]
